/**
 * Import Bids (Part 22F) against the isolated E2E backend and its temporary
 * SQLite file. The workbooks are fictitious and generated by
 * fixtures/make_bid_fixtures.py (deterministic bytes), never real reports.
 *
 * The scenarios share one database and build on each other (first import,
 * re-import, update), so they run serially in this order.
 */
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { DatabaseSync } from "node:sqlite";
import { expect, test, type APIRequestContext, type Page } from "@playwright/test";
import { deleteBidSpecCards } from "./bid-cleanup";
import { API_BASE_URL, E2E_ADMIN_PASSWORD, E2E_ADMIN_USERNAME, loginAsAdmin, loginAsMember } from "./helpers";

const XLSX = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";

test.describe.configure({ mode: "serial" });

const dbPath = process.env.PM_E2E_DB_PATH;
if (!dbPath) throw new Error("PM_E2E_DB_PATH is not set - run through playwright.config.ts");

let fixtures: string;
const fixture = (name: string) => path.join(fixtures, name);

test.beforeAll(() => {
  fixtures = mkdtempSync(path.join(tmpdir(), "pm-e2e-fixtures-"));
  const backend = path.resolve(__dirname, "../../backend");
  execFileSync("uv", ["run", "python", path.resolve(__dirname, "fixtures/make_bid_fixtures.py"), fixtures], {
    cwd: backend,
    env: { ...process.env, PYTHONPATH: backend },
    stdio: "pipe",
  });
});

test.afterAll(async () => {
  if (fixtures) rmSync(fixtures, { recursive: true, force: true });
  await deleteBidSpecCards(dbPath!);
});

// --- helpers -----------------------------------------------------------------

/** Every row of every table the import touches, to prove a step wrote nothing. */
function snapshot(): string {
  const db = new DatabaseSync(dbPath!, { readOnly: true });
  try {
    const tables = [
      "boards", "columns", "cards", "card_bid_details", "card_source_refs", "card_stage_events",
      "card_import_changes", "card_edit_history", "import_batches", "undo_entries",
    ];
    return JSON.stringify(tables.map((t) => db.prepare(`SELECT * FROM ${t} ORDER BY rowid`).all()));
  } finally {
    db.close();
  }
}

function count(table: string): number {
  const db = new DatabaseSync(dbPath!, { readOnly: true });
  try {
    return (db.prepare(`SELECT COUNT(*) AS n FROM ${table}`).get() as { n: number }).n;
  } finally {
    db.close();
  }
}

async function adminHeaders(request: APIRequestContext) {
  const login = await request.post(`${API_BASE_URL}/api/login`, {
    data: { username: E2E_ADMIN_USERNAME, password: E2E_ADMIN_PASSWORD },
  });
  return { Authorization: `Bearer ${(await login.json()).access_token}` };
}

async function openImport(page: Page) {
  await page.goto("/");
  await page.getByRole("button", { name: "Import Bids", exact: true }).click();
  await expect(page.getByRole("heading", { name: "Import Bids" })).toBeVisible();
}

async function choose(page: Page, name: string) {
  await page.getByLabel("Bids report (.xlsx)").setInputFiles(fixture(name));
}

// Next's dev route announcer is an always-present empty role=alert; the screen's own alerts have text.
const importAlert = (page: Page) => page.locator('[role="alert"]').filter({ hasText: /\S/ });
const previewButton = (page: Page) => page.getByRole("button", { name: "Preview", exact: true });
const updatePreview = (page: Page) => page.getByRole("button", { name: "Update preview" });
const confirmButton = (page: Page) => page.getByRole("button", { name: "Confirm import" });
const acknowledge = (page: Page) => page.getByLabel("I reviewed this preview and want to apply it to the board.");
const row = (page: Page, n: number) => page.locator(`tr[data-row="${n}"]`);
const filter = (page: Page, label: string) => page.getByRole("group", { name: "Row filter" }).getByRole("button", { name: new RegExp(`^${label} \\(`) });
const tile = (page: Page, label: string) => page.locator("div", { hasText: new RegExp(`^${label}`) }).first();

async function previewFile(page: Page, name: string) {
  await choose(page, name);
  await previewButton(page).click();
  await expect(page.getByRole("heading", { name: "2. Summary" })).toBeVisible();
}

async function backToBoard(page: Page) {
  await page.getByRole("button", { name: "Board", exact: true }).click();
  await expect(page.locator('[data-testid^="column-"]').first()).toBeVisible();
}

const cardIn = (page: Page, columnIndex: number, title: string) =>
  page.locator('[data-testid^="column-"]').nth(columnIndex).locator(`[data-testid^="card-"][data-title="${title}"]`);

// --- access ----------------------------------------------------------------------

test("a member has no Import Bids entry and the API refuses the member", async ({ page, request }) => {
  await loginAsMember(page, request);
  await page.goto("/");
  await expect(page.locator('[data-testid^="column-"]').first()).toBeVisible();
  await expect(page.getByRole("button", { name: "Import Bids", exact: true })).toHaveCount(0);

  const token = await page.evaluate(() => window.localStorage.getItem("pm_auth_token"));
  const boards = await (await request.get(`${API_BASE_URL}/api/boards`, { headers: { Authorization: `Bearer ${token}` } })).json();
  const url = `${API_BASE_URL}/api/boards/${boards[0].id}/imports`;
  const before = snapshot();
  expect((await request.get(url, { headers: { Authorization: `Bearer ${token}` } })).status()).toBe(403);
  expect((await request.get(url)).status()).toBe(401);
  expect(snapshot()).toBe(before);
});

// --- preview writes nothing ----------------------------------------------------------

test("upload and preview show the plan and write nothing to the database", async ({ page, request }) => {
  await loginAsAdmin(page, request);
  await openImport(page);
  await expect(previewButton(page)).toBeDisabled();

  const before = snapshot();
  await previewFile(page, "bids-initial.xlsx");

  await expect(tile(page, "Rows")).toContainText("4");
  // Row 4 (a closed bid) is only proposed as Lost until the admin confirms it; row 5 has no stage at all.
  await expect(tile(page, "New cards")).toContainText("2");
  await expect(tile(page, "Needs decision")).toContainText("2");
  // Only the rows that need a decision are listed first.
  await expect(filter(page, "Needs decision")).toHaveAttribute("aria-pressed", "true");
  await expect(row(page, 4)).toContainText("E2E Charlie");
  await expect(row(page, 5)).toContainText("E2E Delta");
  await expect(row(page, 2)).toHaveCount(0);
  await filter(page, "All").click();
  await expect(row(page, 2)).toContainText("Proposal");
  await expect(row(page, 3)).toContainText("Award");

  expect(snapshot()).toBe(before);
  await expect(confirmButton(page)).toBeDisabled();

  // Nothing was written and no card exists yet.
  await backToBoard(page);
  await expect(page.locator('[data-testid^="card-"][data-title^="E2E "]')).toHaveCount(0);
  expect(snapshot()).toBe(before);
});

// --- pending decisions, stale preview, confirmation ------------------------------------

test("pending decisions go stale until the preview is updated, then the import is confirmed", async ({ page, request }) => {
  await loginAsAdmin(page, request);
  const batchesBefore = count("import_batches"); // other specs leave their batches behind (no delete API)
  await openImport(page);
  await previewFile(page, "bids-initial.xlsx");

  // Row 4: accept the proposed stage (Lost). Row 5 is left undecided on purpose.
  await row(page, 4).getByLabel(/Accept proposed stage/).check();
  await expect(page.getByText("Your decisions changed since this preview")).toBeVisible();
  await expect(acknowledge(page)).toBeDisabled();
  await expect(confirmButton(page)).toBeDisabled();

  const before = snapshot();
  await updatePreview(page).click();
  await expect(page.getByText("Your decisions changed since this preview")).toHaveCount(0);
  expect(snapshot()).toBe(before); // updating the preview is still read-only
  await expect(tile(page, "Needs decision")).toContainText("1");
  await expect(tile(page, "New cards")).toContainText("3");
  await expect(page.getByText("1 row(s) still need a decision")).toBeVisible();

  // Confirmation needs the explicit acknowledgement.
  await expect(confirmButton(page)).toBeDisabled();
  await acknowledge(page).check();
  await expect(confirmButton(page)).toBeEnabled();
  await confirmButton(page).click();

  const done = page.getByRole("status").filter({ hasText: "completed" });
  await expect(done).toContainText("3 created, 0 updated (0 moved), 0 skipped, 1 left in review");
  // The form is reset for the next file.
  await expect(previewButton(page)).toBeDisabled();
  await expect(confirmButton(page)).toHaveCount(0);

  // Cards landed in their columns: Proposal (3), Award (4), Lost (5); Delta stayed out.
  await backToBoard(page);
  await expect(cardIn(page, 3, "E2E Alpha")).toBeVisible();
  await expect(cardIn(page, 4, "E2E Bravo")).toBeVisible();
  await expect(cardIn(page, 5, "E2E Charlie")).toBeVisible();
  await expect(page.locator('[data-testid^="card-"][data-title="E2E Delta"]')).toHaveCount(0);

  // Import history lists the completed batch with its details and a baseline stage event per card.
  await openImport(page);
  await page.getByRole("tab", { name: "History" }).click();
  const batchRow = page.locator("tbody tr").filter({ hasText: "bids-initial.xlsx" }).first();
  await expect(batchRow).toContainText("completed");
  await expect(batchRow).toContainText("e2e_admin");
  await batchRow.getByRole("button", { name: "Details" }).click();
  const detail = page.getByLabel("Import details");
  await expect(detail.locator("dd", { hasText: /^completed$/ })).toBeVisible();
  await expect(detail).toContainText("SHA-256");
  await expect(detail.locator("div", { hasText: /^Created/ }).first()).toContainText("3");
  await expect(detail.locator("div", { hasText: /^Skipped \/ in review/ }).first()).toContainText("0 / 1");
  expect(count("card_bid_details")).toBe(3);
  expect(count("import_batches")).toBe(batchesBefore + 1);
});

// --- re-import of the same file: unchanged rows, the left-over row now decided -------------

test("re-importing the file creates only the row that was left in review", async ({ page, request }) => {
  await loginAsAdmin(page, request);
  await openImport(page);
  await previewFile(page, "bids-initial.xlsx");

  // Delta has no stage yet, so nothing is creatable until it gets a decision.
  await expect(tile(page, "New cards")).toContainText("0");
  await expect(page.getByText("3 unchanged")).toBeVisible();
  await expect(row(page, 5)).toContainText("Choose a stage");
  await row(page, 5).getByLabel("Stage for row 5").selectOption("1st Contact");
  await updatePreview(page).click();
  await expect(tile(page, "Needs decision")).toContainText("0");
  await expect(tile(page, "New cards")).toContainText("1");
  await filter(page, "New").click();
  await expect(row(page, 5)).toContainText("1st Contact");

  await acknowledge(page).check();
  await confirmButton(page).click();
  await expect(page.getByRole("status").filter({ hasText: "completed" })).toContainText("1 created");

  await backToBoard(page);
  await expect(cardIn(page, 0, "E2E Delta")).toBeVisible();
  // The earlier cards were not duplicated.
  await expect(page.locator('[data-testid^="card-"][data-title="E2E Alpha"]')).toHaveCount(1);
  expect(count("card_bid_details")).toBe(4);
});

// --- update from a newer report: kept out of the member-edit history -----------------------

test("a newer report updates the card after confirmation and stays out of the member edit history", async ({ page, request }) => {
  await loginAsAdmin(page, request);
  await openImport(page);
  await previewFile(page, "bids-update.xlsx");

  await expect(tile(page, "Updates")).toContainText("1");
  await expect(row(page, 2)).toContainText("Confirm the update");
  await row(page, 2).getByRole("button", { name: /Show \d+ change/ }).click();
  await expect(row(page, 2)).toContainText("card.title");
  await expect(row(page, 2)).toContainText("E2E Alpha -> E2E Alpha Renamed");

  // Without the confirmation the update is not applied.
  await acknowledge(page).check();
  await confirmButton(page).click();
  await expect(page.getByRole("status").filter({ hasText: "completed" })).toContainText("0 updated");
  expect(count("card_import_changes")).toBe(0);

  await previewFile(page, "bids-update.xlsx");
  await row(page, 2).getByLabel(/Update card #/).check();
  await updatePreview(page).click();
  await expect(tile(page, "Needs decision")).toContainText("0");
  await acknowledge(page).check();
  await confirmButton(page).click();
  await expect(page.getByRole("status").filter({ hasText: "completed" })).toContainText("0 created, 1 updated (0 moved)");

  await backToBoard(page);
  const card = cardIn(page, 3, "E2E Alpha Renamed");
  await expect(card).toBeVisible();
  await expect(page.locator('[data-testid^="card-"][data-title="E2E Alpha"]')).toHaveCount(0);
  // Import changes are not member edits: no "M" badge, no entry in the card's edit history.
  const cardId = (await card.getAttribute("data-testid"))!.match(/\d+$/)![0];
  const headers = await adminHeaders(request);
  const boards = await (await request.get(`${API_BASE_URL}/api/boards`, { headers })).json();
  const history = await (await request.get(`${API_BASE_URL}/api/boards/${boards[0].id}/cards/${cardId}/history`, { headers })).json();
  expect(history).toEqual([]);
  expect(count("card_edit_history")).toBe(0);
  expect(count("card_import_changes")).toBe(1);
  await expect(card.getByTitle(/edited by a member/i)).toHaveCount(0);
});

// --- errors returned by the backend -------------------------------------------------------

test("a file that is not a workbook is refused with a readable error and nothing is written", async ({ page, request }) => {
  await loginAsAdmin(page, request);
  await openImport(page);
  const before = snapshot();
  await choose(page, "not-a-workbook.xlsx");
  await previewButton(page).click();
  await expect(importAlert(page)).toContainText("The file is not an .xlsx workbook");
  await expect(importAlert(page)).not.toContainText("[object Object]");
  await expect(page.getByRole("heading", { name: "2. Summary" })).toHaveCount(0);
  expect(snapshot()).toBe(before);

  // Choosing another file clears the error.
  await choose(page, "bids-update.xlsx");
  await expect(page.getByRole("button", { name: "Preview", exact: true })).toBeEnabled();
  await expect(importAlert(page)).toHaveCount(0);
});

test("a row with an invalid field is flagged and can only be skipped", async ({ page, request }) => {
  await loginAsAdmin(page, request);
  await openImport(page);
  await previewFile(page, "bids-bad-row.xlsx");

  await expect(tile(page, "Needs decision")).toContainText("1");
  await expect(row(page, 2)).toContainText("Fix the row in the file, or skip it");
  await expect(row(page, 2).getByRole("list").first()).toBeVisible();
  await row(page, 2).getByLabel("Skip this row").check();
  await updatePreview(page).click();
  await expect(tile(page, "Needs decision")).toContainText("0");
  await acknowledge(page).check();
  const batchesBefore = count("import_batches");
  await confirmButton(page).click();
  // Nothing is written, so this is the documented no-op: no batch, not a "completed" import.
  const result = page.getByRole("status").filter({ hasText: "Nothing to import" });
  await expect(result).toContainText("No batch was recorded");
  await expect(result).toContainText("1 skipped");
  await expect(page.getByRole("status").filter({ hasText: "completed" })).toHaveCount(0);
  expect(count("import_batches")).toBe(batchesBefore);
});

// --- conflicts -------------------------------------------------------------------------------

test("a board change after the preview is refused, writes nothing and forces a new preview", async ({ page, request }) => {
  await loginAsAdmin(page, request);
  await openImport(page);
  await previewFile(page, "bids-fresh.xlsx");
  // Nothing needs a decision, so the list opens on "All".
  await expect(filter(page, "All")).toHaveAttribute("aria-pressed", "true");
  await expect(row(page, 2)).toContainText("Proposal");
  await acknowledge(page).check();

  // Meanwhile another admin renames the target stage.
  const headers = await adminHeaders(request);
  const boards = await (await request.get(`${API_BASE_URL}/api/boards`, { headers })).json();
  const board = await (await request.get(`${API_BASE_URL}/api/boards/${boards[0].id}`, { headers })).json();
  const proposal = board.columns.find((c: { title: string }) => c.title === "Proposal");
  const rename = (title: string) =>
    request.put(`${API_BASE_URL}/api/boards/${board.id}/columns/${proposal.id}`, { headers, data: { title } });
  expect((await rename("Quote")).ok()).toBeTruthy();
  try {
    const before = count("cards");
    await confirmButton(page).click();
    await expect(importAlert(page)).toContainText(/changed since the preview/i);
    expect(count("cards")).toBe(before);
    // The old preview cannot be retried: a new one is needed.
    await expect(confirmButton(page)).toHaveCount(0);
    await expect(page.getByRole("heading", { name: "2. Summary" })).toHaveCount(0);
  } finally {
    expect((await rename("Proposal")).ok()).toBeTruthy();
  }

  // With the board restored, a new preview of the same file imports normally.
  await previewButton(page).click();
  await expect(page.getByRole("heading", { name: "2. Summary" })).toBeVisible();
  await acknowledge(page).check();
  await confirmButton(page).click();
  await expect(page.getByRole("status").filter({ hasText: "completed" })).toContainText("1 created");
  await backToBoard(page);
  await expect(cardIn(page, 3, "E2E Echo")).toBeVisible();
});

test("the backend refuses a forged token and a second confirmation of the same preview", async ({ request }) => {
  const headers = await adminHeaders(request);
  const boards = await (await request.get(`${API_BASE_URL}/api/boards`, { headers })).json();
  const imports = `${API_BASE_URL}/api/boards/${boards[0].id}/imports`;
  const multipart = (extra: Record<string, string> = {}) => ({
    file: { name: "bids-replay.xlsx", mimeType: XLSX, buffer: readFileSync(fixture("bids-replay.xlsx")) },
    decisions: "[]",
    ...extra,
  });
  const preview = await request.post(`${imports}/preview`, { headers, multipart: multipart() });
  expect(preview.ok()).toBeTruthy();
  const body = await preview.json();
  expect(body.preview_token).toBeTruthy();

  const forged = await request.post(imports, { headers, multipart: multipart({ preview_token: "forged", confirm: "true" }) });
  expect(forged.status()).toBe(422);

  const before = count("import_batches");
  const first = await request.post(imports, { headers, multipart: multipart({ preview_token: body.preview_token, confirm: "true" }) });
  expect(first.status()).toBe(201);
  const second = await request.post(imports, { headers, multipart: multipart({ preview_token: body.preview_token, confirm: "true" }) });
  expect(second.status()).toBe(409);
  expect(count("import_batches")).toBe(before + 1);
});

test("the history tab lists every batch of the board, newest first", async ({ page, request }) => {
  await loginAsAdmin(page, request);
  await openImport(page);
  await page.getByRole("tab", { name: "History" }).click();
  const rows = page.locator("tbody tr");
  await expect(rows.first()).toBeVisible();
  const ids = (await rows.locator("td:first-child").allTextContents()).map(Number);
  // The list is paginated and other specs leave batches behind: assert on the newest batch, not on a total.
  const newest = new DatabaseSync(dbPath!, { readOnly: true });
  try {
    expect(ids[0]).toBe((newest.prepare("SELECT MAX(id) AS n FROM import_batches").get() as { n: number }).n);
  } finally {
    newest.close();
  }
  expect(ids).toEqual([...ids].sort((a, b) => b - a));
});
